"""Write the C++ header of gameplay constants shared with the map tools.

Build/Content/constants.json is the only definition. The header lands in
Source/CoopRTS/Rules/GameplayConstants.h; the output is deterministic, so
running this twice gives identical bytes.

Run through ./x gen generate-gameplay-constants.
"""

from __future__ import annotations

from pathlib import Path

from ContentText import constants

OUTPUT = (
    Path(__file__).resolve().parent.parent / "Source/CoopRTS/Rules/GameplayConstants.h"
)
BANNER = (
    "// Generated by Build/GenerateGameplayConstants.py from Build/Content/constants.json.\n"
    "// Change the constant there and run ./x gen generate-gameplay-constants; do not edit this file.\n"
)


def pascal(name: str) -> str:
    return "".join(word.capitalize() for word in name.split("_"))


def declaration(name: str, value: int | float) -> str:
    if isinstance(value, int):
        return f"constexpr int32 {pascal(name)} = {value};"
    literal = f"{int(value)}." if value == int(value) else repr(value)
    return f"constexpr float {pascal(name)} = {literal}f;"


def render() -> str:
    lines = [declaration(name, value) for name, value in constants().items()]
    return "\n".join(
        [
            BANNER + "#pragma once",
            "",
            '#include "CoreMinimal.h"',
            "",
            "namespace GameplayConstants",
            "{",
            *lines,
            "}",
            "",
        ]
    )


def write(path: Path) -> None:
    path.write_text(render(), encoding="utf-8", newline="\n")


def main() -> int:
    write(OUTPUT)
    print(f"wrote {OUTPUT.relative_to(OUTPUT.parents[3])}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
